static const z_t6346_t _zag3100 = { { .data = "win_from_errno", .size = 14 }, { .length = 1, .data = _zag3099 }, { .length = 0, .data = NULL }, { .data = "/* the Win32 code for an errno the C runtime set, for the few calls that go\n   through it (_close, the environment) */\nstatic DWORD z_win_from_errno(int e) {\n    switch (e) {\n        case ENOENT: return ERROR_FILE_NOT_FOUND;\n        case EACCES: return ERROR_ACCESS_DENIED;\n        case EEXIST: return ERROR_FILE_EXISTS;\n        case EBADF:  return ERROR_INVALID_HANDLE;\n        case EMFILE: return ERROR_TOO_MANY_OPEN_FILES;\n        case ENOMEM: return ERROR_NOT_ENOUGH_MEMORY;\n        case ENOSPC: return ERROR_DISK_FULL;\n        default:     return ERROR_INVALID_PARAMETER;\n    }\n}", .size = 584 } };
